  const unit = (v, u) => { v = +v; return u === 'kg' || u === 'kilo' || u === 'l' || u === 'liter' ? v * 1000 : u === 'cl' ? v * 10 : v; };
  const multi = t.match(/(\d+)\s*x\s*(\d+(?:\.\d+)?)\s*(kg|kilo|gram|gr|g|ml|liter|cl|l)\b/);
