    storeKey: x.storeKey || null, storeName: x.storeName || null, foodId: strong ? strong.id : null, name: title, cat, n, tags: [...tags], freezable,
    grams: parseUnitSize(x.unitSize) ?? (strong ? strong.pack_g : null), unitSize: x.unitSize || null,
